  "confidence": 0.72,
  "anomalies": [
    {
      "category": "wrong_value",
      "components": ["R25", "R34", "U49"],
      "pins": ["U49.4", "R25.2", "R34.1"],
      "nets": ["VMOT", "NET0120"],
      "observed": "The VMOT voltage-sense divider uses R25 = 50K 0.1% from VMOT to NET0120 and R34 = 5.1K 0.1% from NET0120 to GND. NET0120 feeds U49 pin 4 (ADS1115 AIN0), and U49 is powered from +3V3.",
      "expected": "With VMOT protected by a 51V TVS and using 63V bulk capacitors, the divider must keep the ADS1115 input below its 3.3V supply over the full VMOT range. R34 = 5.1K gives about 3.7V at 41.4V and 4.4V at 48V; the lower resistor should be about 3.3K or less, or the divider ratio changed accordingly.",
      "evidence": [
        {"source": "schematic", "quote": "Motion Sensing sheet: R25 50K 0.1% from VMOT to NET0120; R34 5.1K 0.1% from NET0120 to GND; U49 ADS1115 AIN0 on NET0120; U49 VDD +3V3."},
        {"source": "schematic", "quote": "Power sheet: D16 SMAJ51A on VMOT; C5/C76 47uF 63V solid on VMOT."},
        {"source": "spec", "quote": "Supercap auxiliary board uses eighteen 120F 2.3V supercapacitor cells, consistent with a roughly 41V-class main bus."}
      ],
      "impact": "The input-voltage ADC will saturate or be overvolted at high VMOT, so VMOT sensing will be incorrect and the ADS1115 input may be damaged.",
      "confidence": 0.72
    }
  ],
  "summary": "The VMOT-sense divider feeding the 3.3V ADS1115 is scaled too high: 50K/5.1K can drive the ADC input above its supply on the high-voltage motor bus, so the voltage measurement is not valid over the intended range."
}

